const aliases = new Map(vocabulary.flatMap(([canonical, variants]) => [canonical, ...variants.split(" ")].map(word => [word, canonical])));
const ignored = new Set("a an the how what where why when do does did to of from in on at by for with is are can i my me you your this that it and or as have has please help use using paano ano saan bakit kailan ko po ba ang ng sa si mga ako mo may na at para pwede bang want need would like s yung iyong isang itong kay".split(" "));
export function handbookSearchTerms(value) {
  return [...new Set(String(value).toLowerCase().normalize("NFD").replace(/\p{M}/gu, "")
    .replace(/mag[ -]aaral/g, "magaaral").replace(/get rid of/g, "remove").replace(/[^\p{L}\p{N}]+/gu, " ").trim().split(/\s+/)
    .filter(word => word && !ignored.has(word)).map(word => aliases.get(word) || word))];
}
const searchFields = guide => `${guide.title} ${guide.question} ${guide.text} ${guide.keywords}`;
export function matchesHandbookSearch(guide, query) {
  const terms = handbookSearchTerms(query);
  const available = new Set(handbookSearchTerms(searchFields(guide)));
  return terms.every(term => [...available].some(word => word.includes(term)));
}
export const handbookReference = guides => guides.map(guide => `${guide.title}: ${guide.text}`).join("\n");
const utf8 = new TextEncoder();
export function selectHandbookEntries(role, question, maxBytes = 2400) {
  const guides = handbookHelp[role] || [];
  const terms = handbookSearchTerms(question);
  const ranked = guides.map((guide, index) => {
    const headline = new Set(handbookSearchTerms(`${guide.title} ${guide.question}`));
    const all = new Set(handbookSearchTerms(searchFields(guide)));
    let score = terms.reduce((sum, term) => sum + (headline.has(term) ? 4 : all.has(term) ? 1 : 0), 0);
    for (const phrase of guide.keywords.split("|")) {
      const words = handbookSearchTerms(phrase);
      if (words.length && words.every(word => terms.includes(word))) score += 3 * words.length;
    }
    return { guide, score, index };
  }).sort((a, b) => b.score - a.score || a.index - b.index);
  const selected = [];
  const permissions = guides.find(guide => guide.id === "permissions");
  // Drop weak incidental matches, e.g. deleting a message when removing a learner.
  const minimum = Math.max(4, (ranked[0]?.score || 0) * 0.5);
  const candidates = ranked.filter(item => item.score >= minimum && item.guide !== permissions).map(item => item.guide);
  if (!candidates.length) candidates.push(...guides.filter(guide => guide.id === "dashboard" || guide.id === "support"));
  for (const guide of candidates) {
    if (selected.length >= 3) break;
    const next = [...selected, guide, ...(permissions ? [permissions] : [])];
    if (utf8.encode(handbookReference(next)).length <= maxBytes) selected.push(guide);
  }
  if (permissions && utf8.encode(handbookReference([...selected, permissions])).length <= maxBytes) selected.push(permissions);
  return selected;
}
